import { useState } from 'react'; import { Check, ChevronRight } from 'lucide-react'; import { IndustrialHeader } from './IndustrialHeader';
const IMG_WERKPOST = 'data:image/jpeg;base64,';
interface Props{onComplete:()=>void;elapsedTime:number;productName:string;operatorSettings:{operatorName:string;line:string;station:string};onBack:()=>void;onSettings?:()=>void}
export function ChangeoverStep1Screen({onComplete,elapsedTime,productName,operatorSettings,onBack,onSettings}:Props){const[checklist,setChecklist]=useState([{id:1,label:`Verwijder resterende onderdelen van ${productName}`,checked:false},{id:2,label:'Verwijder gebruikte hulpmiddelen',checked:false},{id:3,label:'Maak het werkoppervlak vrij',checked:false}]);const toggle=(id:number)=>setChecklist(p=>p.map(i=>i.id===id?{...i,checked:!i.checked}:i));const all=checklist.every(i=>i.checked);return <div className="h-full min-h-0 flex flex-col bg-gray-100 overflow-hidden"><IndustrialHeader title="Omstelling, stap 1 van 5" subtitle="Werkpost vrijmaken" showTimer elapsedTime={elapsedTime} operatorSettings={operatorSettings} onBack={onBack} onSettings={onSettings}/><div className="flex-1 min-h-0 overflow-y-auto flex flex-col md:flex-row p-8 gap-8 max-w-[1280px] mx-auto w-full"><div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 p-6"><img src={IMG_WERKPOST} alt="Werkpost vrijmaken" className="w-full h-full min-h-72 object-contain rounded-lg bg-gray-50"/></div><div className="w-full md:w-96 flex flex-col gap-5"><div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6"><h3 className="text-2xl text-gray-800 font-bold mb-3 uppercase">Ruim de werkpost van {productName} op</h3></div><div className="bg-white rounded-lg shadow-sm border border-gray-200 p-5"><h4 className="text-xs uppercase tracking-wider text-gray-500 mb-4 font-medium">Controlelijst</h4><div className="space-y-2">{checklist.map(item=><label key={item.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded cursor-pointer"><input type="checkbox" checked={item.checked} onChange={()=>toggle(item.id)} className="w-6 h-6"/><span className="text-sm text-gray-800 flex-1">{item.label}</span>{item.checked&&<Check className="w-5 h-5 text-green-600"/>}</label>)}</div></div><div className="flex-1"></div><button onClick={onComplete} disabled={!all} className={`w-full text-lg py-4 px-6 rounded-lg flex items-center justify-center gap-3 font-medium ${all?'bg-blue-500 text-white':'bg-gray-300 text-gray-500'}`}>Werkpost vrij<ChevronRight className="w-6 h-6"/></button></div></div></div>}
